138	    public byte[] generaPDFAlpacaForm(String codiceFiscaleRichiedente, AlpacaJsonStructure alpacaStructure, DomandaBando domandaBando, boolean isDelega,
139	                                      String dettagliRichiesta) throws PDFServiceException {
140	
141	        byte[] pdfContent = null;
142	
143	        try {
144	
145	            SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");
146	
147	            Map<String, Object> data = new HashMap<String, Object>();
148	
149	            String htmlContent = null;
150	
151	            long bandoId = domandaBando.getBandoId();
152	            Bando bando = bandoLocalService.getBando(bandoId);
153	            long groupId = bando.getGroupId();
154	            Group group = groupLocalService.getGroup(groupId);
155	
156	            freemarkerTemplateEnteConfiguration = configurationProvider.getGroupConfiguration(FreemarkerTemplateEnteConfiguration.class, groupId);
157	
158	            long organizationId = groupLocalService.getGroup(groupId).getOrganizationId();
159	
160	            Organization organization = organizationLocalService.getOrganization(organizationId);
161	
162	            LayoutSet layout = layoutSetLocalService.getLayoutSet(groupId, false);
163	
164	            String portalUrl = layoutUtility.getSitePath(groupId, group.getCompanyId());
165	            long logoId = layout.getLogoId();
166	
167	            List<AllegatoDTO> allegati = new ArrayList<>();
168	
169	            List<AllegatoDomandaBando> allegatiDomanda =
170	                    allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoId(domandaBando.getDomandaBandoId());
171	
172	            for (AllegatoDomandaBando allegato : allegatiDomanda) {
173	                if (allegato.getDefinizioneAllegatoId() > 0) {
174	                    AllegatoDTO dto = new AllegatoDTO();
175	                    dto.setNomeFile(allegato.getNome());
176	                    if (EsitoVerificaFirma.ERRORE.name().equals(allegato.getEsitoVerificaFirma())) {
177	                        dto.setImpronta("Non disponibile");
178	                    } else {
179	                        dto.setImpronta(allegato.getImpronta());
180	                        dto.setFirmato(allegato.isFirmatoDigitalmente());
181	
182	                        if (Validator.isNotNull(allegato.getFirmatario())) {
183	                            dto.setIdentificativoFirmatario(allegato.getFirmatario());
184	                        }
185	                    }
186	
187	                    allegati.add(dto);
188	                }
189	            }
190	
191	            data.put("logoId", String.valueOf(logoId));
192	
193	            data.put("comune", organization.getName());
194	
195	            data.put("defaultThemeUrl", freemarkerTemplateEnteConfiguration.themeBasePath());
196	            data.put("url", freemarkerTemplateEnteConfiguration.presentatoreFormsBasePath());
197	            data.put("portalUrl", portalUrl);
198	            data.put("delega", Boolean.toString(isDelega));
199	            data.put("dataCorrente", sdf.format(new Date()));
200	            data.put("dettagliRichiesta", dettagliRichiesta);
201	            data.put("denominazioneRichiedente", domandaBando.getUserName());
202	            data.put(GestioneBandiCommonConstants.ALPACA_STRUCTURE, alpacaStructure);
203	            data.put("obbligoAccreditamentoEnte" , String.valueOf(bando.isObbligoAccreditamentoEnte()));
204	            String allegatiJson = new ObjectMapper().writeValueAsString(allegati);
205	            data.put("allegatiJson", allegatiJson);
206	            addParametriAggiuntivi(data, portalUrl);
207	
208	            ByteArrayOutputStream os = new ByteArrayOutputStream();
209	
210	            Template template = getTemplateByTipo(bandoId, CodiceTemplatePdf.ISTANZA.name(), TipoTemplate.FREEMARKER.name()); //TODO per tipo
211	
212	            if(Validator.isNull(template)) {
213	                String templateString = freemarkerTemplateEnteConfiguration.defaultAlpacaTemplate();
214	                Configuration config = new Configuration(Configuration.VERSION_2_3_29);
215	                template = new Template("templateName", new StringReader(templateString), config);
216	            }
217	
218	            template.process(data, new OutputStreamWriter(os));
219	
220	            htmlContent = os.toString(StandardCharsets.UTF_8);
221	            pdfContent = pdfConverter.generatePDF(htmlContent);
222	        }
223	        catch (Exception e) {
224	            log.error("generaPDFAlpacaForm :: " + e.getMessage(), e);
225	            throw new PDFServiceException("Errore durante il processo di generazione del PDF :: " + e.getMessage(), e);
226	        }
227	
228	        return pdfContent;
229	    }
