251	    public byte[] generaPDFDisciplinareForm(DomandaBando domandaBando, AlpacaJsonStructure alpacaStructure, String codice) throws PDFServiceException {
252	
253	        byte[] pdfContent = null;
254	
255	        try {
256	
257	            SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");
258	
259	            Map<String, Object> data = new HashMap<String, Object>();
260	
261	            String htmlContent = null;
262	
263	            long bandoId = domandaBando.getBandoId();
264	            Bando bando = bandoLocalService.getBando(bandoId);
265	            long groupId = bando.getGroupId();
266	            Group group = groupLocalService.getGroup(groupId);
267	
268	            freemarkerTemplateEnteConfiguration = configurationProvider.getGroupConfiguration(FreemarkerTemplateEnteConfiguration.class, groupId);
269	
270	            long organizationId = groupLocalService.getGroup(groupId).getOrganizationId();
271	
272	            Organization organization = organizationLocalService.getOrganization(organizationId);
273	
274	            LayoutSet layout = layoutSetLocalService.getLayoutSet(groupId, false);
275	
276	            String portalUrl = layoutUtility.getSitePath(groupId, group.getCompanyId());
277	
278	            long logoId = layout.getLogoId();
279	            data.put("logoId", String.valueOf(logoId));
280	
281	            data.put("comune", organization.getName());
282	
283	            data.put("defaultThemeUrl", freemarkerTemplateEnteConfiguration.themeBasePath());
284	            data.put("url", freemarkerTemplateEnteConfiguration.presentatoreFormsBasePath());
285	            data.put("portalUrl", portalUrl);
286	            data.put("dataCorrente", sdf.format(new Date()));
287	            data.put("denominazioneRichiedente", domandaBando.getUserName());
288	            data.put("denominazioneBando", bando.getNome());
289	            //	data.put("partitaIva", domandaBando.getPartitaIva());
290	            //	data.put("titoloProgetto", domandaBando.getTitoloProgetto());
291	            JsonObject dataJsonObject = (JsonObject) alpacaStructure.getData();
292	            Map<String, String> mappaValori = convertiData(dataJsonObject);
293	            for (Map.Entry<String, String> entry : mappaValori.entrySet()) {
294	                data.put(entry.getKey(), entry.getValue());
295	            }
296	            data.put(GestioneBandiCommonConstants.ALPACA_STRUCTURE, alpacaStructure);
297	
298	            addParametriAggiuntivi(data, portalUrl);
299	
300	            ByteArrayOutputStream os = new ByteArrayOutputStream();
301	            Template template =  getTemplateByTipo(bandoId, codice, TipoTemplate.FREEMARKER.name());
302	
303	            if(Validator.isNull(template)) {
304	                String templateString = freemarkerTemplateEnteConfiguration.defaultAlpacaTemplate();
305	
306	                if (String.valueOf(CodiceTemplatePdf.REVOCA).equalsIgnoreCase(codice)) {
307	                    templateString = freemarkerTemplateEnteConfiguration.revocaAlpacaTemplate();
308	                }
309	
310	                Configuration config = new Configuration(Configuration.VERSION_2_3_29);
311	                template = new Template("templateName", new StringReader(templateString), config);
312	            }
313	
314	            template.process(data, new OutputStreamWriter(os));
315	
316	            htmlContent = os.toString(StandardCharsets.UTF_8);
317	
318	            String headerHtml = null;
319	            String headerStartMarker = "<!-- DISCIPLINARE_HEADER_START -->";
320	            String headerEndMarker = "<!-- DISCIPLINARE_HEADER_END -->";
321	            int headerStart = htmlContent.indexOf(headerStartMarker);
322	            int headerEnd = htmlContent.indexOf(headerEndMarker);
323	
324	            if (headerStart >= 0 && headerEnd >= 0) {
325	                headerHtml = htmlContent.substring(headerStart + headerStartMarker.length(), headerEnd).trim();
326	                htmlContent = htmlContent.substring(headerEnd + headerEndMarker.length()).trim();
327	            }
328	
329	            pdfContent = pdfConverter.generatePDF(htmlContent, freemarkerTemplateEnteConfiguration.disciplinareWkhtmltopdfParams(), headerHtml);
330	        }
331	        catch (Exception e) {
332	            log.error("generaPDFDisciplinareForm :: " + e.getMessage(), e);
333	            throw new PDFServiceException("Errore durante il processo di generazione del PDF :: " + e.getMessage(), e);
334	        }
335	
336	        return pdfContent;
337	    }
