339	    private Template getTemplateByTipo(long bandoId, String codice, String tipoTemplate)
340	            throws PDFServiceException {
341	
342	        Template templateOut = null;
343	
344	        try {
345	            String template = "";
346	
347	            Configuration config = new Configuration(Configuration.VERSION_2_3_29);
348	            List<TemplatePdf> templatePdfList = templatePdfLocalService.getTemplatePdfByBandoIdAndTipoAndCodice(bandoId, tipoTemplate, codice);
349	
350	            if (ListUtil.isNotNull(templatePdfList) && ListUtil.isNotEmpty(templatePdfList) && templatePdfList.size()==1) {
351	                TemplatePdf templatePdf = templatePdfList.get(0);
352	
353	                if(Validator.isNotNull(templatePdf)){
354	                    long fileEntryId = templatePdf.getFileEntryId();
355	                    FileEntry feTemplate = dlAppService.getFileEntry(fileEntryId);
356	
357	                    if (Validator.isNotNull(feTemplate)) {
358	                        InputStream isTemplate = feTemplate.getContentStream();
359	                        template = new String(isTemplate.readAllBytes(), StandardCharsets.UTF_8);
360	
361	                        if(Validator.isNotNull(template)) {
362	                            templateOut = new Template("templateName", new StringReader(template), config);
363	                        }
364	                    }
365	                }
366	
367	            }
368	
369	        } catch (Exception e) {
370	            log.error("getTemplate :: " + e.getMessage(), e);
371	        }
372	
373	        return templateOut;
374	    }
