753	    private Map<String, String> convertiData(JsonObject dataJsonObject) {
754	        Map<String, String> data = new HashMap<>();
755	        Set<Map.Entry<String, JsonElement>> entrySet = dataJsonObject.entrySet();
756	        for (Map.Entry<String, JsonElement> entry : entrySet) {
757	            String key = entry.getKey();
758	            JsonElement value = entry.getValue();
759	
760	            if (value.isJsonPrimitive()) {
761	                data.put(key, value.getAsString());
762	            } else if (value.isJsonArray()) {
763	                JsonArray array = value.getAsJsonArray();
764	                StringBuilder sb = new StringBuilder();
765	                for (int i = 0; i < array.size(); i++) {
766	                    if (i > 0) sb.append(", ");
767	                    sb.append(array.get(i).getAsString());
768	                }
769	                data.put(key, sb.toString());
770	            } else if (value.isJsonObject()) {
771	                JsonObject jsonObject = value.getAsJsonObject();
772	                Set<Map.Entry<String, JsonElement>> entrySetJsonObject = jsonObject.entrySet();
773	                for (Map.Entry<String, JsonElement> entryJsonObject : entrySetJsonObject) {
774	                    String keyJO = entryJsonObject.getKey();
775	                    JsonElement valueJO = entryJsonObject.getValue();
776	                    data.put(keyJO, valueJO.getAsString());
777	                }
778	            }
779	        }
780	        return data;
781	    }
