@Component(name = "alpacaPDFService", immediate = true, service = PDFService.class, configurationPid = "it.servizidigitali.presentatoreforms.common.configuration.FreemarkerTemplateEnteConfiguration")
public class AlpacaPDFService implements PDFService {

    private static final String SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH = GestioneBandiCommonConstants.SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH;

    private static final Log log = LogFactoryUtil.getLog(AlpacaPDFService.class.getName());

    private ConfigurationProvider configurationProvider;

    private volatile FreemarkerTemplateEnteConfiguration freemarkerTemplateEnteConfiguration;

    @Reference
    protected void setConfigurationProvider(ConfigurationProvider configurationProvider) {
        this.configurationProvider = configurationProvider;
    }

    @Activate
    @Modified
    private void activate(Map<String, Object> props) {
        freemarkerTemplateEnteConfiguration = ConfigurableUtil.createConfigurable(FreemarkerTemplateEnteConfiguration.class, props);
    }

    @Reference
    private OrganizationLocalService organizationLocalService;

    @Reference
    private GroupLocalService groupLocalService;

