    private StatoEsteroLocalService statoEsteroLocalService;

    @Reference
    private ProvinciaLocalService provinciaLocalService;

    @Reference
    private ComuneLocalService comuneLocalService;

    @Reference
    private ComuneEsteroLocalService comuneEsteroLocalService;

    @Reference
    private LayoutSetLocalService layoutSetLocalService;

    @Reference
    private PDFConverter pdfConverter;

    @Reference
    private DLAppService dlAppService;

    @Reference
    private LayoutUtility layoutUtility;

    @Reference
    private TemplatePdfLocalService templatePdfLocalService;

    @Reference
    private BandoLocalService bandoLocalService;

    @Reference
    private AllegatoDomandaBandoLocalService allegatoDomandaBandoLocalService;

    @Reference
    private DomandaBandoIntegrazioneLocalService domandaBandoIntegrazioneLocalService;

    @Override
    public byte[] generaPDFAlpacaForm(String codiceFiscaleRichiedente, AlpacaJsonStructure alpacaStructure, DomandaBando domandaBando, boolean isDelega,
                                      String dettagliRichiesta) throws PDFServiceException {

        byte[] pdfContent = null;

        try {

            SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

            Map<String, Object> data = new HashMap<String, Object>();

            String htmlContent = null;

            long bandoId = domandaBando.getBandoId();
            Bando bando = bandoLocalService.getBando(bandoId);
            long groupId = bando.getGroupId();
            Group group = groupLocalService.getGroup(groupId);

            freemarkerTemplateEnteConfiguration = configurationProvider.getGroupConfiguration(FreemarkerTemplateEnteConfiguration.class, groupId);

            long organizationId = groupLocalService.getGroup(groupId).getOrganizationId();

            Organization organization = organizationLocalService.getOrganization(organizationId);

            LayoutSet layout = layoutSetLocalService.getLayoutSet(groupId, false);

            String portalUrl = layoutUtility.getSitePath(groupId, group.getCompanyId());
            long logoId = layout.getLogoId();

            List<AllegatoDTO> allegati = new ArrayList<>();

            List<AllegatoDomandaBando> allegatiDomanda =
                    allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoId(domandaBando.getDomandaBandoId());

            for (AllegatoDomandaBando allegato : allegatiDomanda) {
                if (allegato.getDefinizioneAllegatoId() > 0) {
                    AllegatoDTO dto = new AllegatoDTO();
                    dto.setNomeFile(allegato.getNome());
                    if (EsitoVerificaFirma.ERRORE.name().equals(allegato.getEsitoVerificaFirma())) {
                        dto.setImpronta("Non disponibile");
                    } else {
                        dto.setImpronta(allegato.getImpronta());
                        dto.setFirmato(allegato.isFirmatoDigitalmente());

                        if (Validator.isNotNull(allegato.getFirmatario())) {
                            dto.setIdentificativoFirmatario(allegato.getFirmatario());
                        }
                    }

                    allegati.add(dto);
                }
            }

            data.put("logoId", String.valueOf(logoId));

            data.put("comune", organization.getName());

            data.put("defaultThemeUrl", freemarkerTemplateEnteConfiguration.themeBasePath());
            data.put("url", freemarkerTemplateEnteConfiguration.presentatoreFormsBasePath());
            data.put("portalUrl", portalUrl);
            data.put("delega", Boolean.toString(isDelega));
            data.put("dataCorrente", sdf.format(new Date()));
            data.put("dettagliRichiesta", dettagliRichiesta);
            data.put("denominazioneRichiedente", domandaBando.getUserName());
            data.put(GestioneBandiCommonConstants.ALPACA_STRUCTURE, alpacaStructure);
            data.put("obbligoAccreditamentoEnte" , String.valueOf(bando.isObbligoAccreditamentoEnte()));
            String allegatiJson = new ObjectMapper().writeValueAsString(allegati);
            data.put("allegatiJson", allegatiJson);
            addParametriAggiuntivi(data, portalUrl);

            ByteArrayOutputStream os = new ByteArrayOutputStream();

            Template template = getTemplateByTipo(bandoId, CodiceTemplatePdf.ISTANZA.name(), TipoTemplate.FREEMARKER.name()); //TODO per tipo

            if(Validator.isNull(template)) {
                String templateString = freemarkerTemplateEnteConfiguration.defaultAlpacaTemplate();
                Configuration config = new Configuration(Configuration.VERSION_2_3_29);
                template = new Template("templateName", new StringReader(templateString), config);
            }

            template.process(data, new OutputStreamWriter(os));

            htmlContent = os.toString(StandardCharsets.UTF_8);
            pdfContent = pdfConverter.generatePDF(htmlContent);
        }
        catch (Exception e) {
            log.error("generaPDFAlpacaForm :: " + e.getMessage(), e);
            throw new PDFServiceException("Errore durante il processo di generazione del PDF :: " + e.getMessage(), e);
        }

        return pdfContent;
    }

    private void addParametriAggiuntivi(Map<String, Object> data, String portalURL) {

        data.put("listaStatiEsteriUrlKey", portalURL + SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH + "/stati-esteri");
        data.put("listaProvinceUrlKey", portalURL + SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH + "/province");
        data.put("listaComuniUrlKey", portalURL + SERVIZI_DIGITALI_REST_CUSTOM_API_ALPACA_PATH + "/comuni");
