    private Map<String, String> convertiData(JsonObject dataJsonObject) {
        Map<String, String> data = new HashMap<>();
        Set<Map.Entry<String, JsonElement>> entrySet = dataJsonObject.entrySet();
        for (Map.Entry<String, JsonElement> entry : entrySet) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();

            if (value.isJsonPrimitive()) {
                data.put(key, value.getAsString());
            } else if (value.isJsonArray()) {
                JsonArray array = value.getAsJsonArray();
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < array.size(); i++) {
                    if (i > 0) sb.append(", ");
                    sb.append(array.get(i).getAsString());
                }
                data.put(key, sb.toString());
            } else if (value.isJsonObject()) {
                JsonObject jsonObject = value.getAsJsonObject();
                Set<Map.Entry<String, JsonElement>> entrySetJsonObject = jsonObject.entrySet();
                for (Map.Entry<String, JsonElement> entryJsonObject : entrySetJsonObject) {
                    String keyJO = entryJsonObject.getKey();
                    JsonElement valueJO = entryJsonObject.getValue();
                    data.put(keyJO, valueJO.getAsString());
                }
            }
        }
        return data;
    }
