package it.servizidigitali.file.utility.converter.pdf;

import com.github.jhonnymertz.wkhtmltopdf.wrapper.Pdf;
import com.github.jhonnymertz.wkhtmltopdf.wrapper.configurations.WrapperConfig;
import com.github.jhonnymertz.wkhtmltopdf.wrapper.params.Param;
import com.liferay.portal.configuration.metatype.bnd.util.ConfigurableUtil;
import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Map;

import org.osgi.service.component.annotations.Activate;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Modified;

import it.servizidigitali.file.utility.configuration.FileConverterConfiguration;
import it.servizidigitali.file.utility.exception.FileConverterException;

/**
 * @author pindi
 *
 */
@Component(name = "PDFConverter", immediate = true, service = PDFConverter.class, configurationPid = "it.servizidigitali.file.utility.configuration.FileConverterConfiguration")
public class PDFConverter {

	private static final Log log = LogFactoryUtil.getLog(PDFConverter.class.getName());

	private volatile FileConverterConfiguration fileConverterConfiguration;

	@Activate
	@Modified
	private void activate(Map<String, Object> props) {
		fileConverterConfiguration = ConfigurableUtil.createConfigurable(FileConverterConfiguration.class, props);
		wkhtmltopdfKeyValueParams = fileConverterConfiguration.wkhtmltopdfKeyValueParams();
		wkhtmltopdfParams = fileConverterConfiguration.wkhtmltopdfParams();
	}

	private String[] wkhtmltopdfKeyValueParams;

	private String[] wkhtmltopdfParams;

	public byte[] generatePDF(String htmlContent) throws FileConverterException {
		return generatePDF(htmlContent, (String[]) null, null);
	}

	public byte[] generatePDF(String htmlContent, String[] additionalKeyValueParams) throws FileConverterException {
		return generatePDF(htmlContent, additionalKeyValueParams, null);
	}

	public byte[] generatePDF(String htmlContent, String[] additionalKeyValueParams, String headerHtml) throws FileConverterException {
		File headerFile = null;
		try {

			Pdf pdf = new Pdf(new WrapperConfig(fileConverterConfiguration.wkhtmltopdfCommandPath()));

			if (wkhtmltopdfParams != null) {
				for (String wkhtmltopdfParam : wkhtmltopdfParams) {
					Param param = new Param(wkhtmltopdfParam);
					pdf.addParam(param);
				}
			}

			addKeyValueParams(pdf, wkhtmltopdfKeyValueParams);
			addKeyValueParams(pdf, additionalKeyValueParams);

			if (headerHtml != null && !headerHtml.isEmpty()) {
				headerFile = File.createTempFile("wk_header_", ".html");
				Files.write(headerFile.toPath(), headerHtml.getBytes(StandardCharsets.UTF_8));
				pdf.addParam(new Param("--header-html", headerFile.getAbsolutePath()));
			}

			pdf.setTimeout(fileConverterConfiguration.wkhtmltopdfTimeout());
			pdf.setAllowMissingAssets();
			pdf.addPageFromString(htmlContent);

			return pdf.getPDF();
		}
		catch (Exception e) {
			log.error("Unable to generate PDF :: " + e.getMessage(), e);
			throw new FileConverterException("Unable to generate PDF :: " + e.getMessage(), e);
		}
		finally {
			if (headerFile != null) {
				headerFile.delete();
			}
		}
	}

	private void addKeyValueParams(Pdf pdf, String[] keyValueParams) {
		if (keyValueParams != null) {
			for (String params : keyValueParams) {
				String[] split = params.split("=", 2);
				if (split.length == 2) {
					pdf.addParam(new Param(split[0].trim(), split[1].trim()));
				}
			}
		}
	}

}

content.text:
Il converter usa **wkhtmltopdf**, e la prima pagina bianca è un classico di questo motore. Le cause tipiche sono nel template/parametri, non in Java:

- un `--header-html` (qui usato **solo** dal disciplinare, righe 69-73) con margini o altezza tali da spingere il contenuto a pagina 2;
- CSS con `page-break-before: always` o un primo elemento con margine/altezza eccessivi;
- margini `--margin-top` troppo grandi nei `wkhtmltopdfParams`.

Per andare al punto giusto e non spulciare tutti i template, mi serve sapere quale caso è quello rotto.

