305				for (var i = 0; i < allegati.length; i++) {
306					var a = allegati[i];
307					var nome = a.nomeFile;
308					var impronta = a.impronta;
309					var firmato = a.firmato === true ? "Sì" : "No";
310					var identificativo = "";
311					if (a.identificativoFirmatario && a.identificativoFirmatario != null) {
312						identificativo = a.identificativoFirmatario;
313					}
314			
315					body += "<tr>";
316					body += "<td style='word-wrap: break-word'>" + nome + "</td>";
317					body += "<td style='word-wrap: break-word'>" + impronta + "</td>";
318					body += "<td style='word-wrap: break-word'>" + firmato + "</td>";
319					body += "<td style='word-wrap: break-word'>" + identificativo + "</td>";
320					body += "</tr>";
321				}
322				body += "</tbody>";
323			
324				// Inserisce tabella completa nel contenitore
