private FirmaRemotaService firmaRemotaService;

@Override
protected void doServeResource(ResourceRequest resourceRequest, ResourceResponse resourceResponse) throws Exception {

    ThemeDisplay themeDisplay = (ThemeDisplay) resourceRequest.getAttribute(WebKeys.THEME_DISPLAY);
    DomandaBando domandaBando = null;

    byte[] pdf = null;

    String screenName = themeDisplay.getUser().getScreenName();

    Gson gson = new Gson();

    try {
        boolean annullamentoDomandaBando = ParamUtil.getBoolean(resourceRequest, PresentatoreFormsPortletKeys.ANNULLAMENTO_DOMANDA_BANDO);
        Bando bando = presentatoreFormFrontendService.getCurrentBando(themeDisplay);
        Contesto contesto = Contesto.valueOf(bando.getContesto());

        if (Validator.isNull(bando)) {
            SessionErrors.add(resourceRequest, PresentatoreFormsPortletKeys.IMPOSSIBILE_RECUPERARE_PROCEDURA);
            return;
        }

        TipoGenerazionePDF tipoGenerazionePDF = null;

        long istanzaFormId = ParamUtil.getLong(resourceRequest, PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID);
        IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService.getIstanzaDomandaBando(istanzaFormId);
        if (Validator.isNotNull(istanzaDomandaBando)) {
            domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());

            // Verifica se il form è di tipo esecuzione
            boolean formEsecuzione = false;
            List<BandoForm> bandoFormList = bandoFormLocalService.getBandoFormBandoAndForm(bando.getBandoId(), istanzaDomandaBando.getFormId());
            if (Validator.isNotNull(bandoFormList) && !bandoFormList.isEmpty()) {
                List<String> tipoFormEsecuzioneList = TipoFormEnum.getTipoFormEsecuzione().stream().map(Enum::name).collect(Collectors.toList());
                String tipoForm = bandoFormList.get(0).getTipoForm();
                formEsecuzione = tipoFormEsecuzioneList.stream().anyMatch(tipo -> tipo.equalsIgnoreCase(tipoForm));
            }

            if(formEsecuzione){
                tipoGenerazionePDF = TipoGenerazionePDF.NATIVA;
            }else{
                tipoGenerazionePDF = TipoGenerazionePDF.valueOf(bando.getTipoGenerazionePDFIstanzaSoccorsoIstruttorio());
            }

            PDFService pdfService = pdfServiceFactory.getPDFService(tipoGenerazionePDF);

            Form form = formLocalService.getForm(istanzaDomandaBando.getFormId());

            FormData formData = AlpacaUtil.loadFormData(form, istanzaDomandaBando.getJson(), true, themeDisplay.getPortalURL());
            AlpacaJsonStructure alpacaStructure = formData.getAlpaca();

            JsonParser jsonParser = new JsonParser();
            alpacaStructure.setSchema(jsonParser.parse(gson.toJson(alpacaStructure.getSchema())).getAsJsonObject());
            alpacaStructure.setOptions(jsonParser.parse(gson.toJson(alpacaStructure.getOptions())).getAsJsonObject());
            alpacaStructure.setData(jsonParser.parse(gson.toJson(alpacaStructure.getData())).getAsJsonObject());

            String fileName = "domandaIntegrativa-" + String.valueOf(domandaBando.getDomandaBandoId()) + "-bando-" + String.valueOf(bando.getBandoId()) + ".pdf";
            String dettagliRichiesta = "";

            if(annullamentoDomandaBando) {
                pdf = pdfService.generaPDFAnnullamento(screenName, alpacaStructure, domandaBando, dettagliRichiesta);
            }else {
                pdf = pdfService.generaPDFIntegrazioni(screenName, alpacaStructure, domandaBando, dettagliRichiesta, istanzaDomandaBando.getIstanzaDomandaBandoId());
            }

            pdf = pdfServiceUtil.generaPDFArchive(pdf);
            if (bando.isSigilloQualificato()) {
                pdf = firmaRemotaService.applicaSigillo(themeDisplay.getScopeGroupId(), 0,contesto, pdf, null, null);
            }

            if (pdf != null && bando.getRichiestaFirmaIntegrazione()) {
                List<it.servizidigitali.common.utility.enumeration.TipoFirmaDigitale> listaFormatiFirma =
