function Normalize-Order($fieldsObj){
  if(-not $fieldsObj){ return }
  $i=0
  $items=@()
  foreach($p in $fieldsObj.PSObject.Properties){
    $hasOrder = $p.Value -and ($p.Value.PSObject.Properties.Name -contains 'order')
    $items += [pscustomobject]@{ Prop=$p; Idx=$i; HasOrder=$hasOrder; Ord= if($hasOrder){[double]$p.Value.order}else{[double]::MaxValue} }
    $i++
  }
  # riassegna order sequenziale solo ai campi che ce l'hanno, ordinati per (order corrente, posizione)
  $withOrder = $items | Where-Object { $_.HasOrder } | Sort-Object Ord, Idx
  $n=1
  foreach($it in $withOrder){ $it.Prop.Value.order = $n; $n++ }
  # ricorsione nei sotto-fields
  foreach($p in $fieldsObj.PSObject.Properties){
    if($p.Value -and ($p.Value.PSObject.Properties.Name -contains 'fields') -and $p.Value.fields){
      Normalize-Order $p.Value.fields
    }
  }
}

